// tc-pedersen.mjs — vendored, dependency-free Pedersen hash on BabyJubJub for classic
// Tornado Cash note commitments (deposit(bytes32 commitment) on the 0.1/1/10/100 ETH pools).
//
// Bit-for-bit port of circomlibjs@0.1.7 src/pedersen_hash.js (default "blake" base-hash path),
// with the base points precomputed by the real circomlibjs (test-commitment.mjs proves equality:
// pedersenCommitmentX(note) === babyJub.unpackPoint(pedersen.hash(note))[0] for random notes).
//
// A 62-byte TC note is 496 bits => 3 segments of 200 bits, so only base points 0..2 are ever
// touched; base 3 is included as margin. Base points generated by circomlibjs getBasePoint("blake", i).

const F = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;
const A = 168700n;
const D = 168696n;
const SUB_ORDER = 2736030358979909402780800718157159386076813972158567259200215660948447373041n;

const BASES = [
  [10457101036533406547632367118273992217979173478358440826365724437999023779287n,
   19824078218392094440610104313265183977899662750282163392862422243483260492317n],
  [2671756056509184035029146175565761955751135805354291559563293617232983272177n,
   2663205510731142763556352975002641716101654201788071096152948830924149045094n],
  [5802099305472655231388284418920769829666717045250560929368476121199858275951n,
   5980429700218124965372158798884772646841287887664001482443826541541529227896n],
  [7107336197374528537877327281242680114152313102022415488494307685842428166594n,
   2857869773864086953506483169737724679646433914307247183624878062391496185654n],
];

const WINDOW_SIZE = 4;
const N_WINDOWS_PER_SEGMENT = 50;

const modF = (x) => ((x % F) + F) % F;
function invF(x) {
  // Fermat inversion
  let e = F - 2n, r = 1n, b = modF(x);
  while (e > 0n) {
    if (e & 1n) r = r * b % F;
    b = b * b % F;
    e >>= 1n;
  }
  return r;
}

// Twisted Edwards addition on BabyJubJub: A*x^2 + y^2 = 1 + D*x^2*y^2
function addPoint(p, q) {
  const [x1, y1] = p, [x2, y2] = q;
  const x1x2 = x1 * x2 % F, y1y2 = y1 * y2 % F;
  const dxxyy = D * x1x2 % F * y1y2 % F;
  const x3 = modF((x1 * y2 + y1 * x2) % F * invF(modF(1n + dxxyy)));
  const y3 = modF((y1y2 - A * x1x2) % F * invF(modF(1n - dxxyy)));
  return [x3, y3];
}

function mulPointEscalar(p, e) {
  let acc = [0n, 1n]; // neutral element
  let base = p;
  let rem = e;
  while (rem > 0n) {
    if (rem & 1n) acc = addPoint(acc, base);
    base = addPoint(base, base);
    rem >>= 1n;
  }
  return acc;
}

// Input a buffer, returns an array of 0/1. Bit 0 is LSB of first byte and so on.
function buffer2bits(buff) {
  const res = new Array(buff.length * 8);
  for (let i = 0; i < buff.length; i++) {
    const b = buff[i];
    res[i * 8] = (b & 0x01);
    res[i * 8 + 1] = (b & 0x02) >> 1;
    res[i * 8 + 2] = (b & 0x04) >> 2;
    res[i * 8 + 3] = (b & 0x08) >> 3;
    res[i * 8 + 4] = (b & 0x10) >> 4;
    res[i * 8 + 5] = (b & 0x20) >> 5;
    res[i * 8 + 6] = (b & 0x40) >> 6;
    res[i * 8 + 7] = (b & 0x80) >> 7;
  }
  return res;
}

// Exact transcription of circomlibjs PedersenHash.hash(), returning the accumulator
// point instead of its packing. The TC commitment is the point's x coordinate.
function pedersenPoint(msg) {
  const bitsPerSegment = WINDOW_SIZE * N_WINDOWS_PER_SEGMENT;
  const bits = buffer2bits(msg);
  const nSegments = Math.floor((bits.length - 1) / (WINDOW_SIZE * N_WINDOWS_PER_SEGMENT)) + 1;
  if (nSegments > BASES.length) throw new Error('message too long for precomputed bases');

  let accP = [0n, 1n];
  for (let s = 0; s < nSegments; s++) {
    let nWindows;
    if (s === nSegments - 1) {
      nWindows = Math.floor(((bits.length - (nSegments - 1) * bitsPerSegment) - 1) / WINDOW_SIZE) + 1;
    } else {
      nWindows = N_WINDOWS_PER_SEGMENT;
    }
    let escalar = 0n;
    let exp = 1n;
    for (let w = 0; w < nWindows; w++) {
      let o = s * bitsPerSegment + w * WINDOW_SIZE;
      let acc = 1n;
      for (let b = 0; ((b < WINDOW_SIZE - 1) && (o < bits.length)); b++) {
        if (bits[o]) {
          acc = acc + (1n << BigInt(b));
        }
        o++;
      }
      if (o < bits.length) {
        if (bits[o]) {
          acc = -acc;
        }
        o++;
      }
      escalar = escalar + acc * exp;
      exp = exp << BigInt(WINDOW_SIZE + 1);
    }
    if (escalar < 0n) {
      escalar = escalar + SUB_ORDER;
    }
    accP = addPoint(accP, mulPointEscalar(BASES[s], escalar));
  }
  return accP;
}

// Commitment for a 62-byte TC note (31-byte nullifier LE buffer || 31-byte secret LE buffer,
// exactly the byte layout tornado-cli writes into the note string):
// commitment = x-coordinate of PedersenHash(note), as a bigint (< F, fits bytes32).
export function pedersenCommitmentX(noteBytes) {
  return pedersenPoint(noteBytes)[0];
}
